fn dif(a: i32, b: i32) -> i32 {
    if a > b { a - b } else { b - a }
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(10) == 0 {
        host::display::state_set(10, 1);
        host::display::state_set(3, w / 2 - 24);
        host::display::state_set(4, h / 2 - 24);
    }
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(5);
    let px: i32 = host::display::pointer_x();
    let py: i32 = host::display::pointer_y();
    let mut mode: i32 = host::display::state_get(2);
    let mut bx: i32 = host::display::state_get(3);
    let mut by: i32 = host::display::state_get(4);
    if down == 1 && prev == 0 && px >= bx && px < bx + 48 && py >= by && py < by + 48 {
        mode = 1;
        host::display::state_set(0, px);
        host::display::state_set(1, py);
        host::display::state_set(8, px - bx);
        host::display::state_set(9, py - by);
    }
    if mode == 1 && down == 1 {
        if dif(px, host::display::state_get(0)) + dif(py, host::display::state_get(1)) > 8 {
            mode = 2;
        }
    }
    if mode == 2 && down == 1 {
        bx = px - host::display::state_get(8);
        by = py - host::display::state_get(9);
    }
    let mut flash: i32 = host::display::state_get(7);
    if down == 0 && mode != 0 {
        if mode == 1 {
            host::display::state_set(6, host::display::state_get(6) + 1);
            flash = 15;
        }
        mode = 0;
    }
    if flash > 0 { flash = flash - 1; }
    host::display::state_set(2, mode);
    host::display::state_set(3, bx);
    host::display::state_set(4, by);
    host::display::state_set(5, down);
    host::display::state_set(7, flash);
    host::display::clear(0x101010);
    let mut c: i32 = 0x8844cc;
    if mode == 2 { c = 0xcc8800; }
    if flash > 0 { c = 0xffffff; }
    host::display::fill_rect(bx, by, 48, 48, c);
    host::display::draw_string(8, 8, "TAPS", 0x808080, 1);
    host::display::draw_number(50, 8, host::display::state_get(6), 0xffffff, 2);
    if mode == 2 {
        host::display::draw_string(8, 30, "DRAGGING", 0xcc8800, 1);
    }
    host::display::present();
}
